<?php

namespace Database\Seeders;

use App\Models\Game;
use Illuminate\Database\Seeder;

/**
 * Real content for the nine games/apps, written from each project's README and design documents,
 * with the owner's media (documents/تصاویر… → public/assets/games/<slug>/).
 * Safe to re-run: `php artisan db:seed --class=GameContentSeeder` (only updates games).
 */
class GameContentSeeder extends Seeder
{
    protected function shots(string $slug, array $captions = [], array $skip = []): array
    {
        $out = [];
        foreach (glob(public_path("assets/games/$slug/shot-*.webp")) ?: [] as $i => $file) {
            $n = $i + 1;
            if (in_array($n, $skip, true)) {
                continue;
            }
            $out[] = ['image' => "assets/games/$slug/".basename($file), 'caption' => $captions[$n] ?? ''];
        }

        return $out;
    }

    protected function video(string $slug, string $key, string $title, int $duration, bool $vertical = true): array
    {
        return ['src' => "assets/games/$slug/$key.mp4", 'poster' => "assets/games/$slug/$key-poster.webp", 'title' => $title, 'duration' => $duration, 'vertical' => $vertical];
    }

